import{_ as i,a0 as l,w as o,s as r,I as n,x as a,a1 as t,A as p,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在系统创建新用户时发送邮件的 Bash 脚本 | LCTT x X-CMD","titleTemplate":false,"description":"在系统创建新用户时发送邮件的 Bash 脚本 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在系统创建新用户时发送邮件的 Bash 脚本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在系统创建新用户时发送邮件的 Bash 脚本 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190801 Bash Script to Send a Mail When a New User Account is Created in System","title":"在系统创建新用户时发送邮件的 Bash 脚本","tag":"201908","desc":""},"relativePath":"201908/20190801 Bash Script to Send a Mail When a New User Account is Created in System.md","filePath":"[post].md"}'),u={name:"201908/20190801 Bash Script to Send a Mail When a New User Account is Created in System.md"};function g(h,s,c,m,k,b){const e=l("Link");return o(),r("div",null,[s[16]||(s[16]=n("h1",{id:"在系统创建新用户时发送邮件的-bash-脚本",tabindex:"-1"},[a("在系统创建新用户时发送邮件的 Bash 脚本 "),n("a",{class:"header-anchor",href:"#在系统创建新用户时发送邮件的-bash-脚本","aria-label":"Permalink to “在系统创建新用户时发送邮件的 Bash 脚本”"},"​")],-1)),s[17]||(s[17]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/07/232807l7x4j7y77555j1j5.jpg",alt:""})],-1)),s[18]||(s[18]=n("p",null,"目前市场上有许多开源监测工具可用于监控 Linux 系统的性能。当系统到达指定的阈值时，它将发送邮件提醒。",-1)),s[19]||(s[19]=n("p",null,"它会监控 CPU 利用率、内存利用率、交换内存利用率、磁盘空间利用率等所有内容。但我不认为它们可以选择监控新用户创建活动，并发送提醒。",-1)),s[20]||(s[20]=n("p",null,"如果没有，这并不重要，因为我们可以编写自己的 bash 脚本来实现这一点。",-1)),s[21]||(s[21]=n("p",null,"我们过去写了许多有用的 shell 脚本。如果要查看它们，请点击以下链接。",-1)),n("ul",null,[n("li",null,[t(e,{href:"https://www.2daygeek.com/category/shell-script/"},{default:p(()=>[...s[0]||(s[0]=[a("如何使用 shell 脚本自动化执行日常任务？",-1)])]),_:1})])]),s[22]||(s[22]=d(`<p>这个脚本做了什么？它监测 <code>/var/log/secure</code> 文件，并在系统创建新帐户时提醒管理员。</p><p>我们不会经常运行此脚本，因为创建用户不经常发生。但是，我打算一天运行一次这个脚本。因此，我们可以获得有关用户创建的综合报告。</p><p>如果在昨天的 <code>/var/log/secure</code> 中找到了 “useradd” 字符串，那么该脚本将向指定的邮箱发送邮件提醒，其中包含了新用户的详细信息。</p><p><strong>注意：</strong>你需要更改邮箱而不是使用我们的邮箱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /opt/scripts/new-user.sh</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#Set the variable which equal to zero</span></span>
<span class="line"><span>prev_count=0</span></span>
<span class="line"><span>count=$(grep -i &quot;\`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot; /var/log/secure | egrep -wi &#39;useradd&#39; | wc -l)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ &quot;$prev_count&quot; -lt &quot;$count&quot; ] ; then</span></span>
<span class="line"><span>  # Send a mail to given email id when errors found in log</span></span>
<span class="line"><span>  SUBJECT=&quot;ATTENTION: New User Account is created on server : \`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot;</span></span>
<span class="line"><span>  # This is a temp file, which is created to store the email message.</span></span>
<span class="line"><span>  MESSAGE=&quot;/tmp/new-user-logs.txt&quot;</span></span>
<span class="line"><span>  TO=&quot;2daygeek@gmail.com&quot;</span></span>
<span class="line"><span>  echo  &quot;Hostname: \`hostname\`&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo -e &quot;\\n&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;The New User Details are below.&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  grep -i &quot;\`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot; /var/log/secure | egrep -wi &#39;useradd&#39; | grep -v &#39;failed adding&#39;| awk &#39;{print $4,$8}&#39; | uniq | sed &#39;s/,/ /&#39; &gt;&gt;  $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  mail -s &quot;$SUBJECT&quot; &quot;$TO&quot; &lt; $MESSAGE</span></span>
<span class="line"><span>  rm $MESSAGE</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>给 <code>new-user.sh</code> 添加可执行权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x /opt/scripts/new-user.sh</span></span></code></pre></div><p>最后添加一个 cron 任务来自动化执行它。它会在每天 7 点运行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0 7 * * * /bin/bash /opt/scripts/new-user.sh</span></span></code></pre></div><p>注意：你将在每天 7 点收到一封邮件提醒，但这是昨天的日志。</p><p>你将会看到类似下面的邮件提醒。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /tmp/logs.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hostname: 2g.server10.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The New User Details are below.</span></span>
<span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>2g.server10.com name=magesh</span></span>
<span class="line"><span>2g.server10.com name=daygeek</span></span>
<span class="line"><span>+------------------------------+</span></span></code></pre></div><hr>`,14)),n("p",null,[s[2]||(s[2]=a("via: ",-1)),t(e,{href:"https://www.2daygeek.com/linux-bash-script-to-monitor-user-creation-send-email/"},{default:p(()=>[...s[1]||(s[1]=[a("https://www.2daygeek.com/linux-bash-script-to-monitor-user-creation-send-email/",-1)])]),_:1})]),n("p",null,[s[7]||(s[7]=a("作者：",-1)),t(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[3]||(s[3]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[8]||(s[8]=a(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[9]||(s[9]=a(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[5]||(s[5]=[a("geekpi",-1)])]),_:1}),s[10]||(s[10]=a(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[6]||(s[6]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:p(()=>[...s[12]||(s[12]=[a("Linux中国",-1)])]),_:1}),s[15]||(s[15]=a(" 荣誉推出",-1))])])}const y=i(u,[["render",g]]);export{w as __pageData,y as default};
